-- Load snowflake_setup/data/*.csv with PUT + COPY INTO (Snowflake CLI or SnowSQL).
-- Generated by snowflake_setup/build_bundle.py. Run from the project folder, after schema.sql:
--   snow sql -f snowflake_setup/schema.sql
--   snow sql -f snowflake_setup/load_from_stage.sql
--
-- DISCLAIMER: This project contains synthetic data and analysis created for
-- demonstration purposes only.

USE SCHEMA LUMENVALE_MMM.PUBLIC;

CREATE OR REPLACE FILE FORMAT LUMENVALE_CSV TYPE = CSV SKIP_HEADER = 1
    FIELD_OPTIONALLY_ENCLOSED_BY = '"' EMPTY_FIELD_AS_NULL = TRUE;
CREATE OR REPLACE TEMPORARY STAGE LUMENVALE_LOAD FILE_FORMAT = LUMENVALE_CSV;
PUT file://snowflake_setup/data/*.csv @LUMENVALE_LOAD AUTO_COMPRESS = TRUE OVERWRITE = TRUE;

COPY INTO MARKETING_SPEND_WEEKLY FROM @LUMENVALE_LOAD/MARKETING_SPEND_WEEKLY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO SALES_WEEKLY FROM @LUMENVALE_LOAD/SALES_WEEKLY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO CONTROLS_WEEKLY FROM @LUMENVALE_LOAD/CONTROLS_WEEKLY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO SYNTHETIC_TRUE_PARAMETERS FROM @LUMENVALE_LOAD/SYNTHETIC_TRUE_PARAMETERS.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_POSTERIOR_DRAWS FROM @LUMENVALE_LOAD/MMM_POSTERIOR_DRAWS.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_RESPONSE_CURVES FROM @LUMENVALE_LOAD/MMM_RESPONSE_CURVES.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_CONTRIBUTIONS_WEEKLY FROM @LUMENVALE_LOAD/MMM_CONTRIBUTIONS_WEEKLY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_CHANNEL_SUMMARY FROM @LUMENVALE_LOAD/MMM_CHANNEL_SUMMARY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_FIT FROM @LUMENVALE_LOAD/MMM_FIT.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_PARAMETER_RECOVERY FROM @LUMENVALE_LOAD/MMM_PARAMETER_RECOVERY.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_MODEL_RUN FROM @LUMENVALE_LOAD/MMM_MODEL_RUN.csv.gz ON_ERROR = ABORT_STATEMENT;
COPY INTO MMM_R_CROSSCHECK FROM @LUMENVALE_LOAD/MMM_R_CROSSCHECK.csv.gz ON_ERROR = ABORT_STATEMENT;
